with Base as (select *, initcap(trim(category)) as category_title from products where supplier_id = 21), products_stats as (select quarter(launch_date) as launch_quarter, supplier_id, count(case when category = 'Home' then 1 end) as home_count from Base group by quarter(launch_date), supplier_id) select launch_quarter, supplier_id, home_count from products_stats order by home_count asc
